  "/static/theme-init.js": "(() => {\n\ttry {\n\t\tconst stored = localStorage.getItem('theme-mode');\n\t\tconst mode = stored === 'dark' || stored === 'light'\n\t\t\t? stored\n\t\t\t: window.matchMedia('(prefers-color-scheme: dark)').matches\n\t\t\t\t? 'dark'\n\t\t\t\t: 'light';\n\t\tdocument.documentElement.setAttribute('data-mode', mode);\n\t\tdocument.documentElement.style.colorScheme = mode;\n\t} catch {\n\t\t// Storage can be unavailable in private or constrained browsing contexts.\n\t}\n})();\n",
  "/svforge-catalog.json": "{\n\t\"$comment\": \"SvelteForge design-system catalog (#240). Generated from the canonical structure (#242). Paths are relative to src/lib/components/svforge/.\",\n\t\"designSystem\": {\n\t\t\"primitives\": {\n\t\t\t\"Button\": { \"path\": \"primitives/Button.svelte\", \"useFor\": [\"actions\", \"form submits\"], \"avoid\": [\"raw button with ad-hoc classes\"] },\n\t\t\t\"Badge\": { \"path\": \"primitives/Badge.svelte\", \"useFor\": [\"status labels\", \"tags\"], \"avoid\": [\"custom span styling\"] },\n\t\t\t\"Toggle\": { \"path\": \"primitives/Toggle.svelte\", \"useFor\": [\"boolean switches\"] },\n\t\t\t\"Checkbox\": { \"path\": \"primitives/Checkbox.svelte\", \"useFor\": [\"multi-select booleans\"] },\n\t\t\t\"Input\": { \"path\": \"primitives/Input.svelte\", \"useFor\": [\"text inputs\"], \"avoid\": [\"raw <input>\"] },\n\t\t\t\"Select\": { \"path\": \"primitives/Select.svelte\", \"useFor\": [\"dropdowns\"], \"avoid\": [\"raw <select>\"] },\n\t\t\t\"Textarea\": { \"path\": \"primitives/Textarea.svelte\", \"useFor\": [\"multi-line text\"], \"avoid\": [\"raw <textarea>\"] }\n\t\t},\n\t\t\"ui\": {\n\t\t\t\"Card\": { \"path\": \"ui/Card.svelte\", \"useFor\": [\"content blocks\", \"stat cards\"], \"avoid\": [\"custom div + border + shadow\"] },\n\t\t\t\"Alert\": { \"path\": \"ui/Alert.svelte\", \"useFor\": [\"info/success/warning/error\"], \"avoid\": [\"alert alert-* classes\"] },\n\t\t\t\"Table\": { \"path\": \"ui/Table.svelte\", \"useFor\": [\"data tables\", \"CRUD lists\"], \"avoid\": [\"raw <table>\"] },\n\t\t\t\"Logo\": { \"path\": \"ui/Logo.svelte\", \"useFor\": [\"brand mark\"] },\n\t\t\t\"Seo\": { \"path\": \"ui/Seo.svelte\", \"useFor\": [\"meta/SEO head\"], \"avoid\": [\"hand-written meta spam\"] },\n\t\t\t\"ThemeToggle\": { \"path\": \"ui/ThemeToggle.svelte\", \"useFor\": [\"application dark/light switching; reuse this ThemeToggle for application theme changes\"], \"avoid\": [\"local button that changes the application theme\"] }\n\t\t},\n\t\t\"layout\": {\n\t\t\t\"Navbar\": { \"path\": \"layout/Navbar.svelte\", \"useFor\": [\"top navigation\"], \"avoid\": [\"custom header per page\"] },\n\t\t\t\"Footer\": { \"path\": \"layout/Footer.svelte\", \"useFor\": [\"page footer\"], \"avoid\": [\"custom footer per page\"] }\n\t\t}\n\t},\n\t\"skeletonSource\": \"@skeletonlabs/skeleton-svelte\",\n\t\"skeletonPrimitives\": [\"Accordion\",\"AppBar\",\"Avatar\",\"Carousel\",\"Collapsible\",\"Combobox\",\"DatePicker\",\"Dialog\",\"FileUpload\",\"FloatingPanel\",\"Listbox\",\"LocaleProvider\",\"Marquee\",\"Menu\",\"Navigation\",\"Pagination\",\"Popover\",\"Portal\",\"Progress\",\"QrCode\",\"RatingGroup\",\"SegmentedControl\",\"Slider\",\"Steps\",\"Switch\",\"Tabs\",\"TagsInput\",\"Toast\",\"ToggleGroup\",\"Tooltip\",\"TreeView\"],\n\t\"rules\": {\n\t\t\"reuseFirst\": \"Prefer reuse over invention. Coherence > originality on first pass.\",\n\t\t\"mustNot\": [\n\t\t\t\"install another UI kit\",\n\t\t\t\"duplicate a Skeleton/SvelteForge primitive\",\n\t\t\t\"hardcode arbitrary colors/radius/spacing when a token exists\"\n\t\t]\n\t},\n\t\"goldenPages\": {\n\t\t\"demo-ui\": { \"template\": \"base\", \"useAs\": \"canonical composition of all svforge components with variants\" },\n\t\t\"admin/users\": { \"template\": \"dashboard\", \"useAs\": \"CRUD list + form patterns\" },\n\t\t\"admin/settings\": { \"template\": \"dashboard\", \"useAs\": \"settings form + Save/Cancel actions\" },\n\t\t\"login\": { \"template\": \"dashboard\", \"useAs\": \"auth form pattern\" }\n\t}\n}\n",
